import health from '@service.health';
import core from './health-core.js';
import adapter from './health-adapter.js';

export const DATA_TYPES = health.DATA_TYPES;

export function getRecent(dataTypes) {
  return adapter.getRecent(health, core, dataTypes);
}

export function subscribe(dataType, onSample, onError) {
  adapter.subscribe(health, core, dataType, onSample, onError);
}

export function unsubscribe(dataType, onError) {
  return adapter.unsubscribe(health, core, dataType, onError);
}


function errorCode(error) {
  return error && typeof error.code === 'number' ? error.code : 200;
}

function normalizeException(core, error) {
  return core.normalizeError(errorCode(error));
}

function getRecent(systemHealth, core, dataTypes) {
  try {
    return Promise.resolve(systemHealth.getRecentSamples({ dataTypes }))
      .then((list) => core.normalizeRecent(list))
      .catch(() => []);
  } catch (error) {
    return Promise.resolve([]);
  }
}

function subscribe(systemHealth, core, dataType, onSample, onError) {
  const fail = (data, code) => {
    if (onError) onError(core.normalizeError(typeof code === 'number' ? code : 200));
  };
  try {
    systemHealth.subscribeSample({
      dataType,
      callback(sample) {
        const normalized = core.normalizeSample(dataType, sample);
        if (normalized && onSample) onSample(normalized);
      },
      fail,
    });
  } catch (error) {
    if (onError) onError(normalizeException(core, error));
  }
}

function unsubscribe(systemHealth, core, dataType, onError) {
  try {
    systemHealth.unsubscribeSample({ dataType });
    return { ok: true };
  } catch (error) {
    const normalized = normalizeException(core, error);
    if (onError) onError(normalized);
    return { ok: false, error: normalized };
  }
}

module.exports = { getRecent, subscribe, unsubscribe };

// service.health 返回值的纯数据规范化层。

function validData(data) {
  return data && typeof data.value === 'number' && typeof data.timeStamp === 'number';
}

function normalizeRecent(list) {
  if (!Array.isArray(list)) return [];
  const normalized = [];
  for (let i = 0; i < list.length; i += 1) {
    const item = list[i];
    if (!item || !validData(item.data)) continue;
    normalized.push({
      ok: true,
      dataType: item.dataType,
      value: item.data.value,
      timeStamp: item.data.timeStamp,
    });
  }
  return normalized;
}

function normalizeSample(dataType, sample) {
  if (!validData(sample)) return null;
  return {
    ok: true,
    dataType,
    value: sample.value,
    timeStamp: sample.timeStamp,
  };
}

function normalizeError(code) {
  return { ok: false, code, unsupported: code === 203 };
}

module.exports = { normalizeRecent, normalizeSample, normalizeError };

