const childProcess = require('child_process');
const fs = require('fs');
const os = require('os');
const path = require('path');

const DEMO_PROVIDER = "export { getRecent, subscribe, unsubscribe, DATA_TYPES } from './demo-health.js';\n";
const EXCLUDED_INPUTS = new Set(['.git', 'node_modules', 'build', 'dist', '.worktrees', 'output']);

function copyProjectInputs(source, destination) {
  fs.mkdirSync(destination, { recursive: true });
  for (const entry of fs.readdirSync(source, { withFileTypes: true })) {
    if (!EXCLUDED_INPUTS.has(entry.name) && (entry.isFile() || entry.isDirectory())) {
      fs.cpSync(path.join(source, entry.name), path.join(destination, entry.name), { recursive: true });
    }
  }

  const nodeModules = path.join(source, 'node_modules');
  if (!fs.existsSync(nodeModules)) {
    throw new Error('node_modules is required for the AIoT demo build');
  }
  fs.symlinkSync(nodeModules, path.join(destination, 'node_modules'), process.platform === 'win32' ? 'junction' : 'dir');
}

function findDebugArtifact(distDirectory) {
  const artifacts = fs.readdirSync(distDirectory, { withFileTypes: true })
    .filter((entry) => entry.isFile() && entry.name.includes('.debug.') && entry.name.endsWith('.rpk'))
    .map((entry) => path.join(distDirectory, entry.name))
    .filter((artifact) => fs.statSync(artifact).size > 0);
  if (artifacts.length !== 1) {
    throw new Error('AIoT demo build did not produce exactly one non-empty debug RPK');
  }
  return artifacts[0];
}

function runNativeBuild(stageProject) {
  const aiotBin = path.join(stageProject, 'node_modules', 'aiot-toolkit', 'lib', 'bin.js');
  if (!fs.existsSync(aiotBin)) {
    throw new Error(`AIoT toolkit binary not found: ${aiotBin}`);
  }
  console.log('> aiot build');
  const result = childProcess.spawnSync(process.execPath, [aiotBin, 'build'], {
    cwd: stageProject,
    encoding: 'utf8',
  });
  const output = `${result.stdout || ''}${result.stderr || ''}`;
  process.stdout.write(output);
  if (result.error) {
    throw result.error;
  }
  if (result.status !== 0) {
    throw new Error(`AIoT demo build failed with exit status ${result.status}`);
  }
}

function createStageRoot() {
  const temporaryDirectory = os.tmpdir();
  if (/[^\x00-\x7f]/.test(temporaryDirectory)) {
    throw new Error(`System temporary directory must be ASCII-only: ${temporaryDirectory}`);
  }
  return fs.mkdtempSync(path.join(temporaryDirectory, 'openvela-demo-'));
}

function publishArtifact(source, outputDirectory) {
  const destinationDirectory = path.join(outputDirectory, 'video', 'official-health-demo-v2', 'demo-rpk');
  fs.mkdirSync(destinationDirectory, { recursive: true });
  const parsedArtifact = path.parse(path.basename(source));
  const timestamp = new Date().toISOString().replace(/[-:.TZ]/g, '');
  let collision = 0;
  let destination;
  do {
    const suffix = collision === 0 ? timestamp : `${timestamp}-${collision}`;
    destination = path.join(destinationDirectory, `${parsedArtifact.name}-${suffix}${parsedArtifact.ext}`);
    collision += 1;
    try {
      fs.closeSync(fs.openSync(destination, 'wx'));
      break;
    } catch (error) {
      if (error.code !== 'EEXIST') {
        throw error;
      }
    }
  } while (true);
  const publishDirectory = fs.mkdtempSync(path.join(destinationDirectory, '.demo-publish-'));
  const temporaryDestination = path.join(publishDirectory, path.basename(source));
  let published = false;
  try {
    fs.copyFileSync(source, temporaryDestination);
    if (fs.statSync(temporaryDestination).size === 0) {
      throw new Error('Copied demo RPK is empty');
    }
    fs.renameSync(temporaryDestination, destination);
    published = true;
    return destination;
  } finally {
    fs.rmSync(publishDirectory, { recursive: true, force: true });
    if (!published) {
      fs.rmSync(destination, { force: true });
    }
  }
}

function buildDemo(projectRoot = process.cwd(), outputDirectory = path.join(projectRoot, 'output'), overrides = {}) {
  const resolvedRoot = path.resolve(projectRoot);
  const resolvedOutput = path.resolve(outputDirectory);
  const operations = {
    copyProjectInputs,
    createStageRoot,
    findDebugArtifact,
    publishArtifact,
    runBuild: runNativeBuild,
    ...overrides,
  };
  const stageRoot = operations.createStageRoot();
  const stageProject = path.join(stageRoot, 'project');
  try {
    operations.copyProjectInputs(resolvedRoot, stageProject);
    fs.writeFileSync(path.join(stageProject, 'src', 'pages', 'index', 'health-provider.js'), DEMO_PROVIDER);
    operations.runBuild(stageProject);
    return operations.publishArtifact(
      operations.findDebugArtifact(path.join(stageProject, 'dist')),
      resolvedOutput,
    );
  } finally {
    fs.rmSync(stageRoot, { recursive: true, force: true });
  }
}

if (require.main === module) {
  try {
    console.log(`Demo RPK: ${buildDemo()}`);
  } catch (error) {
    console.error(error.message);
    process.exitCode = 1;
  }
}

module.exports = {
  buildDemo,
  copyProjectInputs,
  findDebugArtifact,
  runNativeBuild,
};


